  if no=='04':special=['При проведении собеседований обеспечивать свободные выходы и безопасное размещение посетителей; при конфликте не применять силу, обратиться за помощью.']
  build('ИОТ-АДМ-'+no,'для '+title,[[scope]+office1+common1,common2+office2+(['Согласовать маршрут обхода и обязательные средства защиты с ответственным за участок.'] if visit else []),office3+(visit3 if visit else [])+special,common4,common5],'Сверить точное наименование должности, функции, рабочие места, посещаемые зоны, режим работы и необходимые СИЗ.')

